Here’s a basic Flask login flow using Flask-Login and Argon2 password hashing. It assumes you have a SQLAlchemy `User` model with `id`, `username`, and `password_hash` fields; adapt the lookup to your existing database layer.

Install the dependencies:

```bash
pip install Flask-Login Flask-SQLAlchemy argon2-cffi
```

```python
import os

from argon2 import PasswordHasher
from argon2.exceptions import VerificationError, InvalidHashError
from flask import Flask, flash, redirect, render_template, request, url_for
from flask_login import (
    LoginManager, UserMixin, current_user, login_required,
    login_user, logout_user,
)
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config.update(
    SECRET_KEY=os.environ["SECRET_KEY"],  # Set a long, random value in your environment
    SQLALCHEMY_DATABASE_URI=os.environ.get(
        "DATABASE_URL", "sqlite:///app.db"
    ),
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    SESSION_COOKIE_SECURE=not app.debug,  # HTTPS in production
)

db = SQLAlchemy(app)
login_manager = LoginManager(app)
login_manager.login_view = "login"
password_hasher = PasswordHasher()


class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)


@login_manager.user_loader
def load_user(user_id):
    # Flask-Login stores the user ID in the session; reload the user from the DB.
    return db.session.get(User, int(user_id))


@app.route("/login", methods=["GET", "POST"])
def login():
    if current_user.is_authenticated:
        return redirect(url_for("dashboard"))

    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")

        user = User.query.filter_by(username=username).first()

        # Use a generic error so the response doesn't reveal whether the
        # username exists.
        if user:
            try:
                password_hasher.verify(user.password_hash, password)
                login_user(user)
                return redirect(url_for("dashboard"))
            except (VerificationError, InvalidHashError):
                pass

        flash("Invalid username or password.", "error")

    return render_template("login.html")


@app.post("/logout")
@login_required
def logout():
    logout_user()
    return redirect(url_for("login"))


@app.get("/dashboard")
@login_required
def dashboard():
    return render_template("dashboard.html")
```

