```html
<form method="post">
  <!-- Add a CSRF token here if using Flask-WTF. -->
  <label>
    Username
    <input name="username" autocomplete="username" required>
  </label>
  <label>
    Password
    <input name="password" type="password"
           autocomplete="current-password" required>
  </label>
  <button type="submit">Log in</button>
</form>

{% with messages = get_flashed_messages(with_categories=true) %}
  {% for category, message in messages %}
    <p class="{{ category }}">{{ message }}</p>
  {% endfor %}
{% endwith %}
```

When creating a user, hash the password before saving it:

```python
password_hash = password_hasher.hash(password)
user = User(username=username, password_hash=password_hash)
db.session.add(user)
db.session.commit()
```

Use HTTPS in production, keep `SECRET_KEY` out of source control, and add CSRF protection (for example, Flask-WTF) to form submissions. Also consider rate limiting login attempts. If your existing users have bcrypt hashes, don’t compare those hashes with Argon2; verify with bcrypt during a migration, then re-hash the password with Argon2 after a successful login.

Here’s a minimal **Flask session login** using Flask-Login and Werkzeug password hashing. It stores a password hash at registration and checks that stored hash at login—**never create a new hash from the submitted password during login**, since password hashes use salts.

Install the dependencies:

```bash
pip install Flask Flask-SQLAlchemy Flask-Login
```

```python
import os

from flask import Flask, flash, redirect, render_template_string, request, url_for
from flask_login import (
    LoginManager, UserMixin, current_user, login_required,
    login_user, logout_user,
)
from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import check_password_hash, generate_password_hash

app = Flask(__name__)
app.config.update(
    SECRET_KEY=os.environ["SECRET_KEY"],  # Set a long, random secret in your environment
    SQLALCHEMY_DATABASE_URI="sqlite:///app.db",
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    SESSION_COOKIE_SECURE=True,  # Use HTTPS in production
)

db = SQLAlchemy(app)
login_manager = LoginManager(app)
login_manager.login_view = "login"


class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)


@login_manager.user_loader
def load_user(user_id):
    # Flask-Login passes the user ID stored in the session.
    try:
        return db.session.get(User, int(user_id))
    except (TypeError, ValueError):
        return None


@app.route("/register", methods=["GET", "POST"])
def register():
    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")

        if not username or not password:
            flash("Username and password are required.")
        elif len(password) < 12:
            flash("Use a password of at least 12 characters.")
        elif User.query.filter_by(username=username).first():
            flash("That username is already taken.")
        else:
            user = User(
                username=username,
                password_hash=generate_password_hash(password),
            )
            db.session.add(user)
            db.session.commit()
            flash("Account created. You can now log in.")
            return redirect(url_for("login"))

    return render_template_string(FORM, heading="Register", endpoint="register")


@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")
        user = User.query.filter_by(username=username).first()

        if user and check_password_hash(user.password_hash, password):
            login_user(user)
            return redirect(url_for("account"))

        flash("Invalid username or password.")

    return render_template_string(FORM, heading="Log in", endpoint="login")


@app.route("/account")
@login_required
def account():
    return f"Welcome, {current_user.username}!"


@app.post("/logout")
@login_required
def logout():
    logout_user()
    return redirect(url_for("login"))


FORM = """
<h1>{{ heading }}</h1>
{% with messages = get_flashed_messages() %}
  {% for message in messages %}<p>{{ message }}</p>{% endfor %}
{% endwith %}
<form method="post" action="{{ url_for(endpoint) }}">
  <label>Username <input name="username" required></label><br>
  <label>Password <input name="password" type="password" required></label><br>
  <button type="submit">{{ heading }}</button>
</form>
"""


