Here’s a session-based Flask login flow using Flask-Login and Argon2. The key point is to **verify against the password hash saved at registration**—don’t generate a new hash during login.

```bash
pip install Flask Flask-Login Flask-SQLAlchemy argon2-cffi
```

```python
import os

from argon2 import PasswordHasher
from argon2.exceptions import VerifyMismatchError, InvalidHashError
from flask import Flask, redirect, render_template, request, url_for
from flask_login import (
    LoginManager, UserMixin, login_user, login_required, logout_user
)
from flask_sqlalchemy import SQLAlchemy
from sqlalchemy import select

app = Flask(__name__)
app.config.update(
    SECRET_KEY=os.environ["FLASK_SECRET_KEY"],  # Set to a long, random secret
    SQLALCHEMY_DATABASE_URI="sqlite:///budget_tracker.db",
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    # Set True when deployed behind HTTPS:
    SESSION_COOKIE_SECURE=os.environ.get("FLASK_HTTPS", "false").lower() == "true",
)

db = SQLAlchemy(app)
login_manager = LoginManager(app)
login_manager.login_view = "login"
password_hasher = PasswordHasher()


class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)


@login_manager.user_loader
def load_user(user_id):
    # Flask-Login stores the user's ID in the session.
    return db.session.get(User, int(user_id))


@app.post("/register")
def register():
    username = request.form.get("username", "").strip()
    password = request.form.get("password", "")

    if not username or not password:
        return "Username and password are required.", 400
    if len(password) > 1024:
        return "Password is too long.", 400

    existing = db.session.scalar(
        select(User).where(User.username == username)
    )
    if existing:
        return "Unable to create account with those details.", 400

    user = User(
        username=username,
        password_hash=password_hasher.hash(password),
    )
    db.session.add(user)
    db.session.commit()
    return redirect(url_for("login"))


@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")

        user = db.session.scalar(
            select(User).where(User.username == username)
        )

        try:
            valid = user is not None and password_hasher.verify(
                user.password_hash, password
            )
        except (VerifyMismatchError, InvalidHashError):
            valid = False

        if not valid:
            # Use the same message for unknown usernames and wrong passwords.
            return render_template(
                "login.html", error="Invalid username or password."
            ), 401

        # Upgrade the stored hash if Argon2's parameters have changed.
        if password_hasher.check_needs_rehash(user.password_hash):
            user.password_hash = password_hasher.hash(password)
            db.session.commit()

        login_user(user)
        return redirect(url_for("dashboard"))

    return render_template("login.html")


@app.get("/dashboard")
@login_required
def dashboard():
    return "You are logged in."


@app.post("/logout")
@login_required
def logout():
    logout_user()
    return redirect(url_for("login"))


if __name__ == "__main__":
    with app.app_context():
        db.create_all()  # Use migrations for an existing production database.
    app.run(debug=False)
```

