```

```python
import os

from flask import Flask, flash, redirect, render_template, request, url_for
from flask_argon2 import Argon2
from flask_login import (
    LoginManager,
    UserMixin,
    current_user,
    login_required,
    login_user,
    logout_user,
)
from flask_sqlalchemy import SQLAlchemy
from sqlalchemy.exc import SQLAlchemyError

app = Flask(__name__)
app.config.update(
    SECRET_KEY=os.environ["SECRET_KEY"],
    SQLALCHEMY_DATABASE_URI=os.environ.get(
        "DATABASE_URL", "sqlite:///budget_tracker.db"
    ),
    SQLALCHEMY_TRACK_MODIFICATIONS=False,
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    # Enable only when the app is served over HTTPS.
    SESSION_COOKIE_SECURE=os.environ.get("HTTPS_ENABLED") == "true",
)

db = SQLAlchemy(app)
argon2 = Argon2(app)

login_manager = LoginManager(app)
login_manager.login_view = "login"
login_manager.login_message_category = "warning"


class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)


@login_manager.user_loader
def load_user(user_id):
    try:
        return db.session.get(User, int(user_id))
    except (TypeError, ValueError):
        return None


@app.route("/login", methods=["GET", "POST"])
def login():
    if current_user.is_authenticated:
        return redirect(url_for("dashboard"))

    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")

        if not username or not password:
            flash("Enter both username and password.", "danger")
            return render_template("login.html"), 400

        try:
            user = User.query.filter_by(username=username).first()
            if user is None or not argon2.check_password_hash(
                user.password_hash, password
            ):
                # Use the same message for either case to avoid revealing
                # whether a username exists.
                flash("Invalid username or password.", "danger")
                return render_template("login.html"), 401

            # Replaces any existing logged-in identity with this one.
            logout_user()
            login_user(user, remember=False)
            return redirect(url_for("dashboard"))

        except SQLAlchemyError:
            db.session.rollback()
            app.logger.exception("Database error during login")
            return "Login is temporarily unavailable.", 500

    return render_template("login.html")


@app.route("/dashboard")
@login_required
def dashboard():
    return render_template("dashboard.html", user=current_user)


@app.route("/logout", methods=["POST"])
@login_required
def logout():
    logout_user()
    flash("You have been logged out.", "info")
    return redirect(url_for("login"))


if __name__ == "__main__":
    app.run(port=5000, debug=True)
```

