Here’s a minimal Flask-Login example for a Flask + SQLAlchemy app. It accepts JSON at `POST /login`; successful login creates a session cookie.

```bash
pip install Flask Flask-SQLAlchemy Flask-Login
```

```python
import os

from flask import Flask, jsonify, request
from flask_login import (
    LoginManager,
    UserMixin,
    current_user,
    login_required,
    login_user,
    logout_user,
)
from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import check_password_hash

app = Flask(__name__)
app.config.update(
    SECRET_KEY=os.environ["SECRET_KEY"],  # Set to a random secret in your environment
    SQLALCHEMY_DATABASE_URI=os.getenv("DATABASE_URL", "sqlite:///users.db"),
    SQLALCHEMY_TRACK_MODIFICATIONS=False,
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    SESSION_COOKIE_SECURE=os.getenv("FLASK_ENV") == "production",  # HTTPS in production
)

db = SQLAlchemy(app)
login_manager = LoginManager(app)


class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)

    def check_password(self, password: str) -> bool:
        # For hashes created with Werkzeug. If your app stores Argon2 hashes,
        # replace this with your Argon2 library's verification function.
        return check_password_hash(self.password_hash, password)


@login_manager.user_loader
def load_user(user_id: str):
    try:
        return db.session.get(User, int(user_id))
    except (TypeError, ValueError):
        return None


@app.post("/login")
def login():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return jsonify(error="Expected a JSON object"), 400

    username = data.get("username")
    password = data.get("password")
    if not isinstance(username, str) or not username.strip() or not isinstance(password, str) or not password:
        return jsonify(error="Username and password are required"), 400

    user = User.query.filter_by(username=username.strip()).first()
    if user is None or not user.check_password(password):
        return jsonify(error="Invalid username or password"), 401

    login_user(user, remember=False)
    return jsonify(message="Login successful"), 200


@app.get("/session")
@login_required
def session_status():
    return jsonify(user_id=current_user.id, username=current_user.username)


@app.post("/logout")
@login_required
def logout():
    logout_user()
    return jsonify(message="Logged out"), 200
```

Set a strong secret before running, for example with `python -c 'import secrets; print(secrets.token_hex(32))'`, then export it as `SECRET_KEY`. Create the database tables through your existing migration setup (recommended); for a throwaway local test, use `with app.app_context(): db.create_all()`.

If your database already contains Argon2 hashes, do **not** verify them with Werkzeug: replace `check_password_hash` in `check_password()` with the Argon2 verifier you already use. Also protect cookie-authenticated state-changing routes against CSRF, use HTTPS in production, and never run Flask’s debug server in production.

Here is a minimal Flask-Login setup. It assumes a SQLite `users` table with `id`, `username`, and `password_hash` columns, where passwords are stored as Werkzeug password hashes—not plaintext.

```python
import logging
import os
import sqlite3
from logging.handlers import RotatingFileHandler

from flask import Flask, jsonify, request
from flask_login import (
    LoginManager,
    UserMixin,
    current_user,
    login_required,
    login_user,
    logout_user,
)
from werkzeug.security import check_password_hash

app = Flask(__name__)
app.config.update(
    SECRET_KEY=os.environ["SECRET_KEY"],  # Set a long, random secret in the environment
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    # Set True when the app is served over HTTPS:
    SESSION_COOKIE_SECURE=os.environ.get("HTTPS_ONLY", "false").lower() == "true",
)

# Log errors to a rotating file.
handler = RotatingFileHandler("budget_tracker.log", maxBytes=1_000_000, backupCount=3)
handler.setLevel(logging.INFO)
app.logger.addHandler(handler)

login_manager = LoginManager()
login_manager.init_app(app)

DATABASE = os.environ.get("DATABASE_PATH", "budget_tracker.db")


class User(UserMixin):
    def __init__(self, user_id, username, password_hash):
        self.id = str(user_id)  # Flask-Login expects a string ID
        self.username = username
        self.password_hash = password_hash


def get_user_by_id(user_id):
    with sqlite3.connect(DATABASE) as conn:
        conn.row_factory = sqlite3.Row
        return conn.execute(
            "SELECT id, username, password_hash FROM users WHERE id = ?",
            (user_id,),
        ).fetchone()


@login_manager.user_loader
def load_user(user_id):
    try:
        row = get_user_by_id(user_id)
        return User(row["id"], row["username"], row["password_hash"]) if row else None
    except sqlite3.Error:
        app.logger.exception("Failed to load user session")
        return None


@app.post("/login")
def login():
    data = request.get_json(silent=True) or {}
    username = data.get("username", "")
    password = data.get("password", "")
    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify(error="Invalid request"), 400

    try:
        with sqlite3.connect(DATABASE) as conn:
            conn.row_factory = sqlite3.Row
            row = conn.execute(
                "SELECT id, username, password_hash FROM users WHERE username = ?",
                (username,),
            ).fetchone()
    except sqlite3.Error:
        app.logger.exception("Database error during login")
        return jsonify(error="Unable to process login"), 500

    # Use the same response for an unknown username and a wrong password.
    if row is None or not check_password_hash(row["password_hash"], password):
        return jsonify(error="Invalid username or password"), 401

    user = User(row["id"], row["username"], row["password_hash"])
    login_user(user)  # Creates the authenticated session
    return jsonify(message="Login successful"), 200


@app.post("/logout")
@login_required
def logout():
    logout_user()
    return jsonify(message="Logged out"), 200


@app.get("/session")
def session_status():
    if not current_user.is_authenticated:
        return jsonify(authenticated=False), 401
    return jsonify(authenticated=True, username=current_user.username), 200


if __name__ == "__main__":
    app.run()
```

Install the relevant packages with `pip install Flask==2.3.1 Flask-Login==0.6.2`. Set `SECRET_KEY` to a securely generated random value before running the app. When creating users, hash passwords with `werkzeug.security.generate_password_hash(password)` and store the resulting value in `password_hash`. Adjust the table and column names if your existing schema differs. For production, serve over HTTPS and enable the secure session-cookie setting.

Here’s a minimal Flask login flow using **Flask-Login** and Werkzeug password hashing. It assumes users are stored in a SQLite database with a `password_hash` column.

Install the dependencies:

```bash
pip install Flask Flask-SQLAlchemy Flask-Login
```

```python
import os

from flask import Flask, flash, redirect, render_template, request, url_for
from flask_login import (
    LoginManager, UserMixin, current_user, login_required,
    login_user, logout_user,
)
from flask_sqlalchemy import SQLAlchemy
from werkzeug.security import check_password_hash

app = Flask(__name__)
app.config.update(
    SECRET_KEY=os.environ["FLASK_SECRET_KEY"],  # Set this in your environment
    SQLALCHEMY_DATABASE_URI="sqlite:///app.db",
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    # Enable when serving the app exclusively over HTTPS:
    SESSION_COOKIE_SECURE=True,
)

db = SQLAlchemy(app)
login_manager = LoginManager(app)
login_manager.login_view = "login"


class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)


@login_manager.user_loader
def load_user(user_id):
