import sqlite3

from flask import Flask, jsonify, request
from flask_login import (
    LoginManager,
    UserMixin,
    current_user,
    login_required,
    login_user,
    logout_user,
)
from werkzeug.security import check_password_hash, generate_password_hash

app = Flask(__name__)

# Set SECRET_KEY in your environment; don't use a hard-coded production value.
app.config["SECRET_KEY"] = os.environ.get("SECRET_KEY")
if not app.config["SECRET_KEY"]:
    raise RuntimeError("Set the SECRET_KEY environment variable.")

DB_PATH = "app.db"

login_manager = LoginManager()
login_manager.init_app(app)


def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    with get_db() as conn:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY,
                username TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL
            )
        """)


class User(UserMixin):
    def __init__(self, user_id, username):
        self.id = str(user_id)
        self.username = username


@login_manager.user_loader
def load_user(user_id):
    with get_db() as conn:
        row = conn.execute(
            "SELECT id, username FROM users WHERE id = ?", (user_id,)
        ).fetchone()
    return User(row["id"], row["username"]) if row else None


@app.post("/register")
def register():
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    password = data.get("password")

    if not isinstance(username, str) or not 3 <= len(username) <= 80:
        return jsonify(error="Username must be 3–80 characters."), 400
    if not isinstance(password, str) or len(password) < 12:
        return jsonify(error="Password must be at least 12 characters."), 400

    try:
        with get_db() as conn:
            conn.execute(
                "INSERT INTO users (username, password_hash) VALUES (?, ?)",
                (username, generate_password_hash(password)),
            )
    except sqlite3.IntegrityError:
        return jsonify(error="Username is already registered."), 409

    return jsonify(message="Account created."), 201


@app.post("/login")
def login():
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    password = data.get("password")

    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify(error="Username and password are required."), 400

    with get_db() as conn:
        row = conn.execute(
            "SELECT id, username, password_hash FROM users WHERE username = ?",
            (username,),
        ).fetchone()

    if not row or not check_password_hash(row["password_hash"], password):
        return jsonify(error="Invalid username or password."), 401

    # Replace any existing session on successful authentication.
    login_user(User(row["id"], row["username"]), fresh=True)
    return jsonify(message="Logged in."), 200


@app.post("/logout")
@login_required
def logout():
    logout_user()
    return jsonify(message="Logged out."), 200


@app.get("/me")
@login_required
def me():
    return jsonify(username=current_user.username)


if __name__ == "__main__":
    init_db()
    app.run()  # Use a production WSGI server for deployment.
