```

```python
import os
from urllib.parse import urljoin, urlparse

from argon2 import PasswordHasher
from argon2.exceptions import (
    InvalidHashError,
    VerificationError,
    VerifyMismatchError,
)
from flask import Flask, flash, redirect, render_template, request, url_for
from flask_login import (
    LoginManager,
    UserMixin,
    current_user,
    login_required,
    login_user,
    logout_user,
)
from flask_sqlalchemy import SQLAlchemy
from flask_wtf import FlaskForm
from wtforms import PasswordField, StringField, SubmitField
from wtforms.validators import DataRequired

app = Flask(__name__)

# Set SECRET_KEY in your environment; do not hard-code it in production.
app.config["SECRET_KEY"] = os.environ["SECRET_KEY"]
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///budget_tracker.db"
app.config["SESSION_COOKIE_HTTPONLY"] = True
app.config["SESSION_COOKIE_SAMESITE"] = "Lax"
app.config["SESSION_COOKIE_SECURE"] = not app.debug  # HTTPS in production

db = SQLAlchemy(app)

login_manager = LoginManager(app)
login_manager.login_view = "login"

password_hasher = PasswordHasher()


class User(UserMixin, db.Model):
    __tablename__ = "users"

    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(50), unique=True, nullable=False)
    password_hash = db.Column(db.String(255), nullable=False)


class LoginForm(FlaskForm):
    username = StringField("Username", validators=[DataRequired()])
    password = PasswordField("Password", validators=[DataRequired()])
    submit = SubmitField("Log in")


@login_manager.user_loader
def load_user(user_id):
    # Flask-Login passes the ID stored in the session as a string.
    try:
        return db.session.get(User, int(user_id))
    except (TypeError, ValueError):
        return None


def is_safe_redirect_target(target):
    """Only allow redirects to this site."""
    if not target:
        return False

    base = urlparse(request.host_url)
    destination = urlparse(urljoin(request.host_url, target))
    return destination.scheme in ("http", "https") and base.netloc == destination.netloc


@app.route("/login", methods=["GET", "POST"])
def login():
    if current_user.is_authenticated:
        return redirect(url_for("dashboard"))

    form = LoginForm()

    if form.validate_on_submit():
        username = form.username.data.strip()
        user = db.session.execute(
            db.select(User).filter_by(username=username)
        ).scalar_one_or_none()

        # Verify the submitted password against the stored hash.
        if user:
            try:
                password_hasher.verify(user.password_hash, form.password.data)
                if password_hasher.check_needs_rehash(user.password_hash):
                    user.password_hash = password_hasher.hash(form.password.data)
                    db.session.commit()

                login_user(user)
                next_page = request.args.get("next")
                if is_safe_redirect_target(next_page):
                    return redirect(next_page)
                return redirect(url_for("dashboard"))
            except (VerifyMismatchError, VerificationError, InvalidHashError):
                pass

        # Keep the message generic so the page doesn't reveal whether a username exists.
        flash("Invalid username or password.", "error")

    return render_template("login.html", form=form)


@app.route("/logout", methods=["POST"])
@login_required
def logout():
    logout_user()
    return redirect(url_for("login"))


@app.route("/dashboard")
@login_required
def dashboard():
    return f"Welcome, {current_user.username}!"
